package com.opspilot.document.dto; import java.time.*; import com.opspilot.document.*; public record DocumentSummaryResponse(Long id,String title,DocumentStatus status,DocumentCreatorResponse creator,Instant createdAt,Instant updatedAt){public static DocumentSummaryResponse from(Document d){return new DocumentSummaryResponse(d.getId(),d.getTitle(),d.getStatus(),DocumentCreatorResponse.from(d.getCreatedBy()),d.getCreatedAt(),d.getUpdatedAt());}}
